Actionscript.script:
soldierIsInstructor=true;
soldierDefaultPhase=2;
hasDressup=true;enableShoot=true;攻击模式="长枪";
x轴攻击范围=0;y轴攻击范围=24;x轴保持距离=190;攻击欲望=3;命中率=20;
if(!长枪){var pool:Array=_root.敌人函数.大学军校学员随机兵器表;长枪=pool[random(pool.length)];}
根据模式重新读取武器加成=_root.主角函数.根据模式重新读取武器加成;
// CF6 身体接入标准长枪装备、射击和装填；攻击 token 只控制本单位动作所有权。
soldierClock=0;soldierReadyAt=6;soldierNextShootAt=0;soldierTargetName="";soldierAttackOwner=null;
soldierShotCount=0;soldierStabCount=0;soldierReloadCount=0;soldierInvalidMuzzleCount=0;
soldierWeaponError="";
soldierAlignZ=false;soldierApproachX=false;soldierMovementTarget="";
soldierShieldBuffSource="CF6特种兵持盾";soldierBuffError="";soldierShieldReduction=0;soldierShieldGuardDamage=0;
soldierNextShieldGuardAt=0;soldierShieldGuardActive=false;
soldierPhase=2;soldierPhaseChanges=0;soldierPhasePending=false;
soldierShieldStates={长枪站立:"持盾站立",长枪行走:"持盾行走",长枪跑:"持盾跑",
    长枪跳:"持盾被击",近战:"持盾近战",长枪攻击:"持盾攻击",拾取:"持盾站立",
    躲闪:"持盾站立",被击:"持盾被击",击倒:"持盾被击",倒地:"持盾被击",被投:"持盾被击"};
soldierTuning={shootRange:460,knifeRange:95,laneRange:24,keepDistance:190,
    reactionFrames:6,maximumTargetHeight:85,burstShots:3,recoveryFrames:4,
    maximumFireFrames:18,shootRestFrames:30,
    knifeCritChance:10,knifeCritMultiplier:6,knifeExecutePercent:5,secondLifeRatio:0.35,
    laneStopRange:12,approachStopRange:420,shieldDamageReductionPercent:75,shieldGuardTriggerRatio:0.1};

soldierClearMovement=function():Void {
    this.左行=this.右行=this.上行=this.下行=false;
    this.soldierAlignZ=this.soldierApproachX=false;
};

// Generic AI retains targeting. Only this policy supplies inputs consumed by walking.
soldierUpdateMovement=function():Void {
    this.左行=this.右行=this.上行=this.下行=false;
    var target:MovieClip=_root.gameworld[this.攻击目标];
    if(!(target.hp>0) || target===this || target.area==null){this.soldierClearMovement();return;}
    var dx:Number=target._x-this._x,dz:Number=target.Z轴坐标-this.Z轴坐标;
    if(isNaN(dx) || isNaN(dz)){this.soldierClearMovement();return;}
    if(this.soldierMovementTarget!=target._name){
        this.soldierAlignZ=this.soldierApproachX=false;this.soldierMovementTarget=target._name;
    }
    var tune:Object=this.soldierTuning,ax:Number=Math.abs(dx),az:Number=Math.abs(dz);
    if(az>tune.laneRange)this.soldierAlignZ=true;
    else if(az<=tune.laneStopRange)this.soldierAlignZ=false;
    if(ax>tune.shootRange)this.soldierApproachX=true;
    else if(ax<=tune.approachStopRange)this.soldierApproachX=false;
    this.上行=this.soldierAlignZ && dz<0;this.下行=this.soldierAlignZ && dz>0;
    this.左行=this.soldierApproachX && dx<0;this.右行=this.soldierApproachX && dx>0;
};

行走=function():Void {
    if(_root.暂停)return;
    if(_root.控制目标==this._name && _root.控制目标全自动==false){
        _root.敌人函数.行走.call(this);return;
    }
    if(!(this.hp>0) || this.soldierPhase==0 || this.浮空 || this.倒地 || this.硬直中
        || this.soldierAttackOwner!=null){this.soldierClearMovement();return;}
    if(this.状态!="长枪站立" && this.状态!="长枪行走" && this.状态!="长枪跑")return;
    // Re-evaluate at the movement consumer on every frame, after any generic AI write.
    this.soldierUpdateMovement();
    var target:MovieClip=_root.gameworld[this.攻击目标];
    var movingX:Boolean=this.左行 || this.右行,movingZ:Boolean=this.上行 || this.下行;
    var running:Boolean=movingX && Math.abs(target._x-this._x)>this.soldierTuning.shootRange;
    if(movingX){
        var direction:String=this.右行?"右":"左";this.方向改变(direction);
        var speedX:Number=running?this.跑X速度:this.行走X速度;
        this.移动(direction,Math.min(speedX,Math.max(0,Math.abs(target._x-this._x)-this.soldierTuning.approachStopRange)));
    }
    if(movingZ){
        var speedZ:Number=running?this.跑Y速度:this.行走Y速度;
        this.移动(this.下行?"下":"上",Math.min(speedZ,Math.max(0,Math.abs(target.Z轴坐标-this.Z轴坐标)-this.soldierTuning.laneStopRange)));
    }
    this.状态改变(movingX || movingZ?(running?"长枪跑":"长枪行走"):"长枪站立");
};

soldierApplyShieldBuff=function():Void {
    if(this.soldierPhase!=1)return;
    var reduction:Number=this.特种兵持盾减伤率==undefined?this.soldierTuning.shieldDamageReductionPercent:Number(this.特种兵持盾减伤率);
    if(isNaN(reduction) || reduction<0 || reduction>99){
        this.soldierBuffError="持盾减伤率须在 0 到 99 之间";trace("[CF6Soldier] "+this.soldierBuffError);
        reduction=this.soldierTuning.shieldDamageReductionPercent;
    }
    this.soldierShieldReduction=reduction;
    if(reduction==0)return;
    if(this.buffManager==null || typeof _root.技能函数.霸体减伤!="function"){
        this.soldierBuffError="持盾减伤的标准 Buff 入口缺失";trace("[CF6Soldier] "+this.soldierBuffError);return;
    }
    _root.技能函数.霸体减伤(this,reduction,0,this.soldierShieldBuffSource);
    this.buffManager.update(0);
};

soldierRemoveShieldBuff=function():Void {
    _root.技能函数.移除霸体减伤(this,this.soldierShieldBuffSource);
};

soldierCancelAttack=function():Void {
    if(this.soldierAttackOwner!=null) this.soldierAttackOwner.active=false;
    this.soldierAttackOwner=null;this.动作A=false;
    _root.主角函数.清理射击任务(this);
};

soldierCanShieldGuard=function():Boolean {
    if(this.soldierPhase!=1 || !(this.hp>0) || this.浮空 || this.倒地 || this.soldierClock<this.soldierNextShieldGuardAt)return false;
    if(this.状态=="长枪站立" || this.状态=="长枪行走" || this.状态=="长枪跑"
        || this.状态=="拾取" || this.状态=="躲闪")return true;
    var owner:Object=this.soldierAttackOwner;
    return this.状态=="长枪攻击" && (owner==null || (owner.action=="shoot" && !owner.charge
        && (!owner.elite || owner.kind=="stand")));
};

// Cancel before the timeline unloads its old man; delayed shots cannot adopt a new pose.
状态改变=function(next:String):Void {
    if(this.soldierPhase==0)return;
    if(this.soldierPhase==1 && (next=="血腥死" || next=="消失")){
        this.soldierSetHP(0);return;
    }
    if(this.状态==next)return;
    if(next!="被击")this.soldierEndShieldGuard();
    if(this.soldierPhase!=1)this.soldierClearShieldPressure();
    this.soldierCancelAttack();
    this.状态=next;
    var pose:String=this.soldierPhase==1?this.soldierShieldStates[next]:next;
    if(next=="长枪攻击" && typeof this.cf6UnitIdentity=="string" && this.cf6ExpectedPose=="dual")
        pose="固定双枪攻击";
    else if(next=="长枪攻击" && this.soldierIsInstructor===true && this.eliteNextAction=="line")
        pose=this.soldierPhase==1?"教官持盾阵地攻击":"教官阵地攻击";
    else if(next=="长枪攻击" && this.soldierIsElite===true && typeof this.cf6UnitIdentity=="string" && this.eliteNextAction=="line")
        pose=this.soldierPhase==1?"固定持盾阵地攻击":"固定阵地攻击";
    this.gotoAndStop(pose);
};

soldierSetHP=function(value:Number):Void {
    if(isNaN(value))return;
    if(this.soldierPhase==0)return;
    if(this.soldierPhase==1 && value<=0){
        this.soldierHP=1;this.soldierPhase=0;this.soldierPhasePending=true;
        this.soldierClearShieldPressure();this.soldierEndShieldGuard();
        this.soldierPhaseChanges++;this.soldierCancelAttack();
        this.soldierClearMovement();this.soldierRemoveShieldBuff();
        return;
    }
    var previous:Number=this.soldierHP;
    this.soldierHP=value;
    if(this.soldierPhase==1){
        if(value>=this.hp满血值)this.soldierClearShieldPressure();
        else this.soldierRecordShieldPressure(previous,value);
    }
};

soldierOnKill=function(target:MovieClip):Void {
    if(this.soldierPhase==1){this.soldierSetHP(0);return;}
    if(this.soldierPhase==0 || this._killed || this.hp>0)return;
    var airborne:Boolean=this.浮空===true && this.状态=="击倒";
    if(typeof this.cf6FixedDeath=="function")this.cf6FixedDeath();
    _root.敌人函数.标准击杀(this);
    if(airborne){this.浮空=true;this.状态改变("击倒");}
};

soldierInitializePhase=function():Void {
    var requested:Number=Number(this.特种兵初始阶段);
    if(requested!=1 && requested!=2){
        if(this.特种兵初始阶段!=undefined)trace("[CF6Soldier] invalid initial phase: "+this.特种兵初始阶段);
        requested=this.soldierDefaultPhase;
    }
    this.soldierPhase=this.soldierInitialPhase=requested;
    this.soldierInitializeDefense();
    this.soldierNormalHitEffect=this.击中效果 || "飙血";
    this.击中效果=requested==1?"击中金属":this.soldierNormalHitEffect;
    this.soldierHP=Number(this.hp);
    this.soldierExternalRigid=this.刚体===true;
    this.soldierExternalInvincible=this.无敌===true;
    this.addProperty("hp",function():Number {return this.soldierHP;},
        function(value:Number):Void {this.soldierSetHP(Number(value));});
    this.addProperty("刚体",function():Boolean {return this.soldierPhase!=2 || this.soldierExternalRigid;},
        function(value:Boolean):Void {this.soldierExternalRigid=value===true;});
    this.addProperty("无敌",function():Boolean {return this.soldierPhase==0 || this.soldierExternalInvincible;},
        function(value:Boolean):Void {this.soldierExternalInvincible=value===true;});
    this.soldierStandardDeathCheck=this.死亡检测;
    this.死亡检测=function(para:Object):Void {
        if(this.soldierPhase!=2 || this.soldierDeathSettled)return;
        if(this.hp<=0){
            if(typeof this.cf6FixedDeath=="function")this.cf6FixedDeath();
            this.soldierDeathSettled=true;
        }
        this.soldierStandardDeathCheck.call(this,para);
    };
    this.dispatcher.subscribeSingle("kill",this.soldierOnKill,this);
    this.soldierApplyShieldBuff();
    this.状态="";this.状态改变("长枪站立");
};

soldierBeginBreak=function():Void {
    if(this.soldierPhase!=0 || !this.soldierPhasePending)return;
    this.soldierPhasePending=false;
    this.soldierPhaseToken={};
    this.状态="破盾";this.gotoAndStop("破盾");
};

soldierFinishBreak=function(body:MovieClip):Void {
    if(_root.暂停 || this.soldierPhase!=0 || body!==this.man
        || body.soldierPhaseToken!==this.soldierPhaseToken)return;
    this.soldierPhase=2;this.soldierPhaseToken=null;
    // This timeline callback runs outside BuffManager.update. Flush only queued removals.
    if(this.buffManager!=null)this.buffManager.update(0);
    this.soldierShieldReduction=0;
    this.击中效果=this.soldierNormalHitEffect;
    this.soldierHP=Math.max(1,Math.round(this.hp满血值*this.soldierTuning.secondLifeRatio));
    this.浮空=this.倒地=this.硬直中=false;this.remainingImpactForce=0;
    this.soldierReadyAt=this.soldierClock+this.soldierTuning.reactionFrames;
    this.状态改变("长枪站立");
};

soldierBeginAttack=function(body:MovieClip,action:String):Void {
    this.soldierCancelAttack();
    if(!(this.hp>0)){body.stop();return;}
    var token:Object={};body.soldierToken=token;
    this.soldierAttackOwner={token:token,action:action,active:true,lastHitFrame:0,
        target:this.攻击目标,weapon:this.长枪,version:this.version,age:0,shots:0,recovery:0,reload:false};
    if(action=="shoot") {
        if(this.soldierClock<this.soldierNextShootAt){this.soldierFinishAttack(body);return;}
        if(!(this.长枪弹匣容量>0) || !(this.长枪属性.interval>0)
            || typeof _root.主角函数.初始化长枪射击函数!="function") {
            this.soldierWeaponError="长枪数据或标准射击入口缺失";
            trace("[CF6Soldier] "+this._name+" "+this.soldierWeaponError);
            this.soldierFinishAttack(body);return;
        }
        // The unit owns the deadline across pose changes, hits and target swaps.
        // No new attack or cancelled scheduler may reset the mandatory ceasefire.
        this.soldierAttackOwner.fireDeadline=this.soldierClock+this.soldierTuning.maximumFireFrames;
        this.soldierNextShootAt=this.soldierAttackOwner.fireDeadline+this.soldierTuning.shootRestFrames;
        body.初始化长枪射击函数=_root.主角函数.初始化长枪射击函数;
        body.初始化长枪射击函数();
    }
};

soldierCanAct=function(body:MovieClip):Boolean {
    var owner:Object=this.soldierAttackOwner;
    return !_root.暂停 && this.soldierPhase!=0 && this.hp>0 && !this.硬直中 && owner!=null && owner.active
        && body===this.man && body.soldierToken===owner.token && owner.version===this.version
        && (owner.action!="shoot" || owner.weapon===this.长枪)
        && this.状态==(owner.action=="knife"?"近战":"长枪攻击");
};

soldierFinishAttack=function(body:MovieClip):Void {
    var owner:Object=this.soldierAttackOwner;
    if(owner==null || body!==this.man || owner.token!==body.soldierToken)return;
    this.soldierCancelAttack();this.动画完毕();
};

soldierMuzzleMarker=function(body:MovieClip):MovieClip {
    var outer:MovieClip=body.枪,holder:MovieClip=outer.枪,gun:MovieClip=holder.装扮;
    var marker:MovieClip=gun.枪口位置;
    if(outer._parent!==body || holder._parent!==outer || gun._parent!==holder
        || marker._parent!==gun || gun!==this.长枪_引用)return null;
    return marker;
};

soldierMuzzle=function(body:MovieClip):Object {
    var marker:MovieClip=this.soldierMuzzleMarker(body);if(marker==null)return null;
    var p:Object={x:0,y:0};marker.localToGlobal(p);var globalY:Number=p.y;
    _root.gameworld.globalToLocal(p);if(isNaN(p.x) || isNaN(p.y))return null;
    p.globalY=globalY;return p;
};

// ShootCore chooses cadence and WeaponFireCore commits ammunition and bullet properties.
长枪射击=function(marker:MovieClip,props:Object):Boolean {
    var body:MovieClip=this.man,owner:Object=this.soldierAttackOwner;
    var limit:Number=owner.charge?owner.shotLimit:this.soldierTuning.burstShots;
    if(!this.soldierCanAct(body) || owner.action!="shoot" || owner.reload
        || owner.shots>=limit
        || !(this.soldierClock<owner.fireDeadline))return false;
    if(marker!==this.soldierMuzzleMarker(body) || marker==null){this.soldierInvalidMuzzleCount++;return false;}
    var fired:Boolean=_root.主角函数.长枪射击.call(this,marker,props);
    if(fired){owner.shots++;this.soldierShotCount++;if(owner.shots>=limit)this.动作A=false;}
    return fired;
};

soldierReloadStart=function(body:MovieClip):Void {
    if(!this.soldierCanAct(body)){body.stop();return;}
    this.动作A=false;this.soldierAttackOwner.reload=true;this.soldierReloadCount++;
    _root.主角函数.初始化换弹负担(body,15,35,18,49,[35,47]);
};

soldierReloadEnd=function(body:MovieClip):Void {
    if(!this.soldierCanAct(body)){body.stop();return;}
    body.结束换弹();this.soldierFinishAttack(body);
};

soldierDriveShooting=function(body:MovieClip):Void {
    var owner:Object=this.soldierAttackOwner;owner.age++;
    if(owner.reload){_root.主角函数.换弹帧率控制(body);return;}
    if(!(this.soldierClock<owner.fireDeadline)){this.soldierFinishAttack(body);return;}
    if(owner.shots>=this.soldierTuning.burstShots){
        if(++owner.recovery>=this.soldierTuning.recoveryFrames)this.soldierFinishAttack(body);
        return;
    }
    if(owner.age<3)return;
    if(this.soldierMuzzleMarker(body)==null){
        if(owner.age>30){this.soldierWeaponError="长枪外观或枪口引用缺失";
            trace("[CF6Soldier] "+this._name+" "+this.soldierWeaponError);this.soldierFinishAttack(body);}
        return;
    }
    this.动作A=true;body.开始射击();
};

soldierStab=function(body:MovieClip,point:MovieClip):Void {
    if(!this.soldierCanAct(body) || point.area==null) return;
    var owner:Object=this.soldierAttackOwner;
    if(owner.action!="knife" || owner.lastHitFrame==body._currentframe) return;
    owner.lastHitFrame=body._currentframe;
    var p:Object={x:point._x,y:point._y};body.localToGlobal(p);_root.gameworld.globalToLocal(p);
    this.soldierStabCount++;
    // Snapshot numbers, not the shooter's lifetime, into the standard crit callback.
    var critChance:Number=this.soldierTuning.knifeCritChance;
    var critMultiplier:Number=this.soldierTuning.knifeCritMultiplier;
    _root.子弹区域shoot传递({声音:"",霰弹值:1,子弹散射度:0,发射效果:"",
        子弹种类:"近战子弹",子弹威力:this.空手攻击力,子弹速度:0,
        暴击:function(bullet:Object):Number {return _root.成功率(critChance)?critMultiplier:1;},
        斩杀:this.soldierTuning.knifeExecutePercent,
        Z轴攻击范围:24,击中地图效果:"",发射者:this._name,
        shootX:p.x,shootY:p.y,shootZ:this.Z轴坐标,击倒率:10,
        击中后子弹的效果:"空手攻击火花",水平击退速度:2,垂直击退速度:1,
        区域定位area:point.area});
};

soldierChooseAttack=function(dx:Number,dz:Number,height:Number):String {
    var tune:Object=this.soldierTuning;
    if(isNaN(dx) || isNaN(dz) || isNaN(height) || dx<0 || dz<0
        || dz>tune.laneRange || height>tune.maximumTargetHeight || this.soldierClock<this.soldierReadyAt) return "none";
    if(dx<=tune.knifeRange) return "knife";
    if(dx<=tune.shootRange && !(this.soldierClock<this.soldierNextShootAt)) return "shoot";
    return "none";
};

soldierTick=function():Void {
    if(this.soldierPhase==0){
        if(_root.暂停)return;
        this.soldierBeginBreak();
        var body:MovieClip=this.man;
        if(body.soldierPhaseToken===this.soldierPhaseToken){
            if(body._currentframe>=11)this.soldierFinishBreak(body);
            else body.nextFrame();
        }
        return;
    }
    if(_root.暂停)return;
    this.soldierClock++;
    if(this.soldierTacticalConfig!=null)this.soldierTacticalObserve();
    if(!isNaN(this.hp) && this.hp<=0){
        this.soldierSlidePermit=null;this.soldierCancelAttack();
        if(this.浮空 && this.状态=="击倒")return;
        if(this.倒地 && this.状态=="倒地")return;
        if(this.状态!="血腥死" && this.状态!="消失")this.状态改变("血腥死");
        return;
    }
    this.soldierObserveShieldThreat();
    if(this.soldierTryShieldGuard())return;
    var owner:Object=this.soldierAttackOwner;
    if(owner!=null && !this.soldierCanAct(this.man)){
        this.soldierCancelAttack();
        if(this.状态=="长枪攻击" || this.状态=="近战" || this.状态=="投掷手雷")this.动画完毕();
        return;
    }
    if(!(this.hp>0) || this.倒地 || this.浮空 || this.硬直中)return;
    if(owner!=null){if(owner.action=="shoot")this.soldierDriveShooting(this.man);else if(owner.action=="grenade")this.soldierDriveGrenade(this.man);return;}
    if(_root.控制目标==this._name && _root.控制目标全自动==false)return;
    if(this.状态!="长枪站立" && this.状态!="长枪行走" && this.状态!="长枪跑")return;
    if((this.soldierClock&3)!=0)return;
    this.x轴攻击范围=0;this.y轴攻击范围=this.soldierTuning.laneRange;
    this.x轴保持距离=this.soldierTuning.keepDistance;
    if(this.unitAI.data!=null){
        this.unitAI.data.xrange=0;this.unitAI.data.zrange=this.y轴攻击范围;
        this.unitAI.data.xdistance=this.x轴保持距离;
    }
    var target:MovieClip=_root.gameworld[this.攻击目标];
    if(!(target.hp>0) || target==this || target.area==null)return;
    var dx:Number=target._x-this._x,dz:Number=target.Z轴坐标-this.Z轴坐标;
    var height:Number=target.Z轴坐标-target._y;
    if(target.浮空高度!=undefined && !isNaN(target.浮空高度) && target.浮空高度>0)height+=target.浮空高度;
    if(isNaN(dx) || isNaN(dz) || isNaN(height))return;
    if(this.soldierTargetName!=target._name){
        this.soldierTargetName=target._name;
        this.soldierReadyAt=this.soldierClock+this.soldierTuning.reactionFrames;
    }
    var action:String=this.soldierChooseAttack(Math.abs(dx),Math.abs(dz),height);
    if(action=="none"){
        this.soldierUpdateMovement();
        return;
    }
    this.soldierClearMovement();
    if(dx<0)this.方向改变("左");else if(dx>0)this.方向改变("右");
    this.状态改变(action=="knife"?"近战":action=="grenade"?"投掷手雷":"长枪攻击");
};

// Pressure is recorded independently of the current animation's interruptibility.
// These scalar transitions are also executed verbatim by the offline Node runner.
soldierShieldGuardPending=false;soldierShieldGuardRequestAt=0;soldierShieldGuardHits=0;
soldierShieldGuardLastHitAt=-1000;soldierShieldGuardBuffActive=false;
soldierShieldGuardCount=0;soldierShieldGuardFirstAt=-1;soldierShieldGuardThreatCount=0;
soldierShieldGuardBuffSource="CF6特种兵架盾";
soldierTuning.shieldGuardTriggerRatio=0.025;
soldierTuning.shieldGuardHitWindow=12;soldierTuning.shieldGuardHitCount=3;
soldierTuning.shieldGuardRestFrames=90;soldierTuning.shieldGuardReductionPercent=85;
soldierTuning.shieldGuardHoldStart=13;soldierTuning.shieldGuardHoldEnd=50;
soldierTuning.shieldGuardThreatETA=12;

soldierInitializeDefense=function():Void {
    var key:String=typeof this.cf6UnitIdentity=="string"?this.cf6UnitIdentity:this._name;
    var hash:Number=0;
    for(var i:Number=0;i<length(key);i++)hash=(hash*31+key.charCodeAt(i))%65521;
    // Stable identity affects timing without consuming the game's random stream.
    this.soldierShieldGuardDelay=this.特种兵防御错峰===false?0:hash%5;
    this.soldierShieldGuardRatio=this.soldierTuning.shieldGuardTriggerRatio
        *(this.特种兵防御错峰===false?1:0.8+(hash%5)*0.1);
    this.soldierShieldGuardRest=this.soldierTuning.shieldGuardRestFrames
        +(this.特种兵防御错峰===false?0:(hash%7)*3);
    this.soldierShieldGuardProactive=this.特种兵主动架盾===true
        || (this.特种兵主动架盾!==false && hash%3==0);
};

soldierQueueShieldGuard=function(urgent:Boolean):Void {
    var ready:Number=this.soldierClock+(urgent?0:this.soldierShieldGuardDelay);
    if(!this.soldierShieldGuardPending || ready<this.soldierShieldGuardRequestAt)
        this.soldierShieldGuardRequestAt=ready;
    this.soldierShieldGuardPending=true;
};

soldierRecordShieldPressure=function(previous:Number,value:Number):Void {
    if(this.soldierPhase!=1 || !(value>0) || !isFinite(previous) || !isFinite(value)
        || !(previous>value) || !(this.hp满血值>0))return;
    var damage:Number=previous-value;
    this.soldierShieldGuardDamage+=damage;
    if(this.soldierClock-this.soldierShieldGuardLastHitAt>this.soldierTuning.shieldGuardHitWindow)
        this.soldierShieldGuardHits=0;
    this.soldierShieldGuardLastHitAt=this.soldierClock;
    this.soldierShieldGuardHits++;
    var threshold:Number=Math.max(1,this.hp满血值*this.soldierShieldGuardRatio);
    if(this.soldierShieldGuardDamage>=threshold
        || this.soldierShieldGuardHits>=this.soldierTuning.shieldGuardHitCount)
        this.soldierQueueShieldGuard(this.soldierShieldGuardDamage>=this.hp满血值*0.08);
};

soldierClearShieldPressure=function():Void {
    this.soldierShieldGuardPending=false;this.soldierShieldGuardDamage=0;
    this.soldierShieldGuardHits=0;this.soldierShieldGuardLastHitAt=-1000;
};

soldierEndShieldGuard=function():Void {
    if(this.cf6GuardImpactPending && this.soldierShieldGuardActive && this.soldierPhase==1
        && this.状态=="被击" && (this.man._currentframe==62 || this.man._currentframe==124))
        this.cf6Signals.event(this,"shield");
    this.cf6GuardImpactPending=false;
    this.soldierShieldGuardActive=false;
    if(this.soldierShieldGuardBuffActive){
        this.soldierShieldGuardBuffActive=false;
        _root.技能函数.移除霸体减伤(this,this.soldierShieldGuardBuffSource);
    }
};

soldierGuardPose=function(body:MovieClip,held:Boolean):Void {
    if(body!==this.man || this.soldierPhase!=1 || this.状态!="被击"
        || !this.soldierShieldGuardActive || !(this.hp>0))return;
    if(held){
        if(this.soldierShieldGuardBuffActive)return;
        if(this.buffManager==null || typeof _root.技能函数.霸体减伤!="function")return;
        this.soldierShieldGuardBuffActive=true;
        _root.技能函数.霸体减伤(this,this.soldierTuning.shieldGuardReductionPercent,0,this.soldierShieldGuardBuffSource);
    }else{
        if(!this.soldierShieldGuardBuffActive)return;
        this.soldierShieldGuardBuffActive=false;
        _root.技能函数.移除霸体减伤(this,this.soldierShieldGuardBuffSource);
    }
    // Timeline callbacks run outside the damage setter / BuffManager tick.
    this.buffManager.update(0);
};

soldierTryShieldGuard=function():Boolean {
    if(!this.soldierShieldGuardPending || this.soldierShieldGuardActive
        || this.soldierClock<this.soldierShieldGuardRequestAt || !this.soldierCanShieldGuard())return false;
    this.soldierClearShieldPressure();this.soldierShieldGuardActive=true;
    this.soldierShieldGuardCount++;
    if(this.soldierShieldGuardFirstAt<0)this.soldierShieldGuardFirstAt=this.soldierClock;
    this.soldierNextShieldGuardAt=this.soldierClock+this.soldierShieldGuardRest;
    this.soldierReadyAt=this.soldierClock;
    this.soldierClearMovement();
    // Preserve the weapon's existing ceasefire; defense cannot grant a free burst.
    this.状态改变("被击");
    return true;
};

soldierObserveShieldThreat=function():Void {
    if(!this.soldierShieldGuardProactive || this.soldierPhase!=1 || this.soldierShieldGuardActive
        || this.soldierClock<this.soldierNextShieldGuardAt || !(this._btCount>0))return;
    var age:Number=_root.帧计时器.当前帧数-this._btFrame;
    var eta:Number=this._btMinETA;
    if(!isFinite(age) || age<0 || age>1 || !isFinite(eta) || eta<0
        || !(eta<this.soldierTuning.shieldGuardThreatETA))return;
    this.soldierShieldGuardThreatCount++;
    this.soldierQueueShieldGuard(false);
};

// Ordinary positional combat and elite shield mobility share existing weapon services.
soldierNextMeleeAt=0;soldierNextBashAt=0;soldierNextGrenadeAt=90;
soldierBashCount=0;soldierGrenadeCount=0;soldierChargeCount=0;soldierDebrisStampCount=0;
soldierGrenadeError="";soldierMeleeKind="knife";
soldierTuning.bashRange=60;soldierTuning.bashRestFrames=90;soldierTuning.meleeRestFrames=18;
soldierTuning.chargeRange=650;soldierTuning.chargeStopRange=130;soldierTuning.chargeStageRange=230;
soldierRoleChoose=soldierChooseAttack;soldierRoleDrive=soldierDriveShooting;
soldierRoleCanAct=soldierCanAct;soldierRoleReload=soldierReloadStart;
soldierRoleInitialize=soldierInitializePhase;soldierRoleBreak=soldierFinishBreak;
soldierRoleFinish=soldierFinishAttack;soldierRoleMove=soldierUpdateMovement;
soldierRoleWalk=行走;

soldierInitializePhase=function():Void {
    if(this.特种兵投掷物==undefined)this.特种兵投掷物="高爆手雷";
    var frames:Number=Number(this.特种兵投掷冷却帧);
    this.soldierGrenadeRest=isFinite(frames) && frames>=36?frames:210;
    this.soldierRoleInitialize();
};
soldierCanGrenade=function():Boolean {
    if((this.soldierIsElite===true && this.soldierIsInstructor!==true) || this.soldierPhase!=2 || this.特种兵投掷物===false || this.特种兵投掷物=="")return false;
    var item:Object=_root.getItemData(this.特种兵投掷物),data:Object=item.data;
    return item.use=="手雷" && typeof data.bullet=="string" && data.bullet!="" && isFinite(data.power) && data.power>0;
};
soldierChooseAttack=function(dx:Number,dz:Number,height:Number):String {
    var tune:Object=this.soldierTuning;
    if(isNaN(dx) || isNaN(dz) || isNaN(height) || dx<0 || dz<0
        || height>tune.maximumTargetHeight || this.soldierClock<this.soldierReadyAt)return "none";
    if(this.soldierIsElite===true && this.soldierPhase==1){
        return dz<=tune.laneRange && dx>=tune.chargeStageRange && dx<=tune.chargeRange
            && !(this.soldierClock<this.soldierNextShootAt)?"shoot":"none";
    }
    if(dx>=180 && dx<=480 && dz<=80 && !(this.soldierClock<this.soldierNextGrenadeAt)
        && this.soldierCanGrenade())return "grenade";
    if(dx<=tune.knifeRange && dz<=tune.laneRange){
        if(this.soldierClock<this.soldierNextMeleeAt)return "none";
        this.soldierMeleeKind=this.soldierPhase==1 && dx<=tune.bashRange
            && !(this.soldierClock<this.soldierNextBashAt)?"bash":"knife";
        return "knife";
    }
    return this.soldierRoleChoose(dx,dz,height);
};
soldierCanAct=function(body:MovieClip):Boolean {
    var owner:Object=this.soldierAttackOwner;
    if(owner.action!="grenade")return this.soldierRoleCanAct(body);
    return !_root.暂停 && this.hp>0 && this.soldierPhase==2 && !this.硬直中
        && !this.倒地 && !this.浮空 && owner.active && owner.version===this.version
        && body===this.man && body.soldierToken===owner.token && this.状态=="投掷手雷"
        && owner.itemName===this.特种兵投掷物 && (this.soldierIsElite!==true || this.soldierIsInstructor===true);
};
soldierBeginMelee=function(body:MovieClip):Void {
    if(this.soldierIsElite===true && this.soldierIsInstructor!==true){body.stop();this.动画完毕();return;}
    this.soldierBeginAttack(body,"knife");
    var owner:Object=this.soldierAttackOwner;
    if(owner==null)return;
    owner.bash=this.soldierMeleeKind=="bash";
    this.soldierNextMeleeAt=this.soldierClock+34+this.soldierTuning.meleeRestFrames;
    if(owner.bash){this.soldierNextBashAt=this.soldierClock+this.soldierTuning.bashRestFrames;body.gotoAndPlay("挥盾");}
};
soldierMeleeHit=function(body:MovieClip,point:MovieClip):Void {
    if(!this.soldierCanAct(body) || point.area==null)return;
    var owner:Object=this.soldierAttackOwner;
    if(owner.action!="knife" || owner.meleeCommitted)return;
    owner.meleeCommitted=true;
    if(!owner.bash){this.soldierStab(body,point);return;}
    var p:Object={x:point._x,y:point._y};body.localToGlobal(p);_root.gameworld.globalToLocal(p);
    this.soldierBashCount++;
    _root.子弹区域shoot传递({声音:"",霰弹值:1,子弹散射度:0,发射效果:"",子弹种类:"近战子弹",
        子弹威力:this.空手攻击力*0.6,子弹速度:0,暴击:function(bullet:Object):Number {return 1;},斩杀:0,Z轴攻击范围:24,
        发射者:this._name,shootX:p.x,shootY:p.y,shootZ:this.Z轴坐标,击倒率:10,
        击中地图效果:"",击中后子弹的效果:"空手攻击火花",水平击退速度:24,垂直击退速度:0,区域定位area:point.area});
};
soldierFinishAttack=function(body:MovieClip):Void {
    var owner:Object=this.soldierAttackOwner;
    if(owner.action=="knife" && body===this.man && owner.token===body.soldierToken)
        this.soldierNextMeleeAt=this.soldierClock+this.soldierTuning.meleeRestFrames;
    this.soldierRoleFinish(body);
};
soldierBeginGrenade=function(body:MovieClip):Void {
    this.soldierCancelAttack();
    if(!this.soldierCanGrenade() || !(this.hp>0)){body.stop();this.动画完毕();return;}
    var token:Object={};body.soldierToken=token;
    var target:MovieClip=_root.gameworld[this.攻击目标];
    this.soldierAttackOwner={token:token,action:"grenade",active:true,version:this.version,
        itemName:this.特种兵投掷物,targetX:target._x,sign:this.方向=="左"?-1:1,thrown:false,age:0};
    this.soldierNextGrenadeAt=this.soldierClock+this.soldierGrenadeRest;body.stop();
};
soldierDriveGrenade=function(body:MovieClip):Void {
    var owner:Object=this.soldierAttackOwner;
    owner.age++;
    if(owner.age>=36){this.soldierFinishAttack(body);return;}
    body.gotoAndStop(owner.age+1);
    if(owner.age>=24 && !owner.thrown)this.soldierThrowGrenade(body);
};
soldierThrowGrenade=function(body:MovieClip):Void {
    if(!this.soldierCanAct(body))return;
    var owner:Object=this.soldierAttackOwner;
    if(owner.thrown)return;
    owner.thrown=true;
    var data:Object=_root.getItemData(owner.itemName).data;
    if(!(data.power>0) || typeof data.bullet!="string"){this.soldierGrenadeError="投掷物配置失效";return;}
    var gravity:Number=Number(_root.重力加速度);
    if(!(gravity>0))gravity=1;
    // The grenade asset owns its -5 vertical launch and gravity. Match the
    // horizontal travel to that flight, keeping the throw a committed aim.
    var release:Object={x:0,y:0};body.投掷手.localToGlobal(release);_root.gameworld.globalToLocal(release);
    if(!isFinite(release.x) || !isFinite(release.y)){this.soldierGrenadeError="投掷手挂点失效";return;}
    var height:Number=Math.max(1,this.Z轴坐标-release.y);
    var flight:Number=(5+Math.sqrt(25+2*height*gravity))/gravity;
    var distance:Number=Math.abs(owner.targetX-release.x);
    if(!isFinite(distance))distance=300;
    var velocity:Number=Math.min(Number(data.velocity)>0?Number(data.velocity):25,Math.max(4,distance/flight));
    var bullet:MovieClip=_root.子弹区域shoot传递({声音:"",霰弹值:1,子弹散射度:0,发射效果:"",
        子弹种类:data.bullet,子弹威力:Number(data.power),子弹速度:velocity,
        速度X:owner.sign*velocity,速度Y:0,子弹大小:data.bulletsize,
        Z轴攻击范围:10,击倒率:10,发射者:this._name,发射者名:this._name,
        子弹敌我属性值:this.是否为敌人,shootX:release.x,
        shootY:release.y,shootZ:this.Z轴坐标,击中地图效果:"",击中后子弹的效果:""});
    if(bullet!=null)this.soldierGrenadeCount++;else this.soldierGrenadeError="投掷物资源未加载";
};
soldierBeginCharge=function(body:MovieClip):Void {
    this.soldierBeginAttack(body,"shoot");
    var owner:Object=this.soldierAttackOwner;
    if(owner==null)return;
    if(this.soldierIsElite!==true || this.soldierPhase!=1){this.soldierFinishAttack(body);return;}
    owner.charge=!this.soldierShieldCoverFire;owner.coverFire=this.soldierShieldCoverFire===true;owner.age=0;owner.distance=0;owner.blockedFrames=0;owner.lastChargeX=this._x;
    owner.sign=this.方向=="左"?-1:1;
    var config:Object=this.soldierTacticalConfig;
    owner.shotLimit=config.chargeShots;owner.turns=0;owner.chargeMovedZ=0;
    owner.fireDeadline=this.soldierClock+(owner.coverFire?config.rifleFireFrames:config.chargeWindupFrames+config.chargeActiveFrames);
    this.soldierNextShootAt=owner.fireDeadline+(owner.coverFire?config.rifleRestFrames:config.chargeRestFrames);
    if(owner.charge)this.soldierChargeCount++;
    body.prepareStandardShotPose=function(frame:String):Void {};
    body.stop();
};
soldierDriveShooting=function(body:MovieClip):Void {
    var owner:Object=this.soldierAttackOwner;
    if(!owner.charge){this.soldierRoleDrive(body);return;}
    if(owner.reload){_root.主角函数.换弹帧率控制(body);return;}
    owner.age++;
    var config:Object=this.soldierTacticalConfig;
    var windup:Number=config.chargeWindupFrames,active:Number=config.chargeActiveFrames;
    if(owner.age>=windup+active+config.chargeRecoveryFrames){this.soldierFinishAttack(body);return;}
    if(owner.age<windup){body.gotoAndStop(1+Math.floor(owner.age*9/windup));return;}
    if(owner.age>=windup+active){
        body.gotoAndStop(Math.min(46,35+Math.floor((owner.age-windup-active)*11/config.chargeRecoveryFrames)));
        this.动作A=false;_root.主角函数.清理射击任务(this);return;
    }
    body.gotoAndStop(11+Math.min(23,Math.floor((owner.age-windup)*24/active)));
    var target:MovieClip=_root.gameworld[owner.target];
    owner.lastChargeX=this._x;
    this.soldierChargeContact(owner);
    // Contact is an impact, not a brake. Finish the committed run through the target.
    if(owner.contactCommitted && target.hp>0 && owner.turns<config.chargeMaxTurns
        && owner.age>owner.contactAge+4 && (target._x-this._x)*owner.sign<-config.chargeTurnDistance){
        owner.sign=-owner.sign;owner.turns++;this.soldierTacticalStats.chargeTurns++;
        this.方向改变(owner.sign<0?"左":"右");
    }
    if(owner.distance>=config.chargeMaxDistance || owner.blockedFrames>=3){
        owner.age=windup+active;body.gotoAndStop(35);
        this.动作A=false;_root.主角函数.清理射击任务(this);return;
    }
    if(owner.distance<config.chargeMaxDistance && owner.blockedFrames<3){
        var speed:Number=Math.min(12,Math.max(2,Number(this.跑X速度)*config.chargeSpeed));
        if(!isFinite(speed))speed=7;
        speed=Math.min(speed,config.chargeMaxDistance-owner.distance);
        var moved:Number=this.soldierTacticalMove(owner.sign<0?"左":"右",speed);
        owner.distance+=moved;
        if(target.hp>0 && owner.chargeMovedZ<config.chargeZBudget){
            var dz:Number=target.Z轴坐标-this.Z轴坐标;
            if(Math.abs(dz)>this.soldierTuning.laneStopRange){
                var zstep:Number=Math.min(this.跑Y速度*config.chargeZSpeed,Math.abs(dz)-this.soldierTuning.laneStopRange,
                    config.chargeZBudget-owner.chargeMovedZ);
                owner.chargeMovedZ+=this.soldierTacticalMove(dz<0?"上":"下",zstep);
            }
        }
        if(moved<0.1)owner.blockedFrames++;else owner.blockedFrames=0;
        this.soldierChargeContact(owner);
        if(moved<0.1){owner.age=windup+active;body.gotoAndStop(35);this.动作A=false;_root.主角函数.清理射击任务(this);return;}
    }
    if(owner.shots<owner.shotLimit && this.soldierMuzzleMarker(body)!=null){
        this.动作A=true;body.开始射击();
    }
};
soldierReloadStart=function(body:MovieClip):Void {
    var owner:Object=this.soldierAttackOwner;
    if(!owner.charge && !owner.coverFire){this.soldierRoleReload(body);return;}
    if(!this.soldierCanAct(body)){body.stop();return;}
    this.动作A=false;owner.reload=true;this.soldierReloadCount++;
    _root.主角函数.初始化换弹负担(body,47,67,50,81,[67,79]);
};
soldierUpdateMovement=function():Void {
    if(this.soldierIsElite!==true || this.soldierPhase!=1){this.soldierRoleMove();return;}
    this.soldierRoleMove();
    var target:MovieClip=_root.gameworld[this.攻击目标];
    if(!(target.hp>0))return;
    var dx:Number=target._x-this._x,ax:Number=Math.abs(dx);
    var stop:Number=this.soldierTacticalConfig.chargeRange-40;
    this.左行=ax>stop && dx<0;this.右行=ax>stop && dx>0;
};
行走=function():Void {
    if(this.soldierIsElite!==true || this.soldierPhase!=1
        || (_root.控制目标==this._name && _root.控制目标全自动==false)){this.soldierRoleWalk();return;}
    if(_root.暂停 || !(this.hp>0) || this.硬直中 || this.soldierAttackOwner!=null)return;
    if(this.状态!="长枪站立" && this.状态!="长枪行走" && this.状态!="长枪跑")return;
    this.soldierUpdateMovement();
    var target:MovieClip=_root.gameworld[this.攻击目标];
    if(!(target.hp>0))return;
    var dx:Number=target._x-this._x,dz:Number=target.Z轴坐标-this.Z轴坐标;
    if(dx!=0)this.方向改变(dx<0?"左":"右");
    var moving:Boolean=this.左行 || this.右行 || this.上行 || this.下行;
    if(this.左行 || this.右行)this.移动(this.右行?"右":"左",Math.min(this.行走X速度,Math.max(0,Math.abs(dx)-(this.soldierTacticalConfig.chargeRange-40))));
    if(this.上行 || this.下行)this.移动(this.下行?"下":"上",Math.min(this.行走Y速度,Math.max(0,Math.abs(dz)-12)));
    this.状态改变(moving?"长枪行走":"长枪站立");
};
soldierFinishBreak=function(body:MovieClip):Void {
    // The shield and its successor share this root. Commit at its settled
    // ground position, not while the lethal hit is still transporting it.
    if(_root.敌人函数.换相位移未结束(this))return;
    if(!_root.暂停 && this.soldierPhase==0 && body===this.man
        && body.soldierPhaseToken===this.soldierPhaseToken && !this.soldierDebrisStamped){
        var debris:MovieClip=body.盾碎片;
        if(debris!=null && _root.gameworld.deadbody.layers[2]!=null && typeof _root.add2map=="function"){
            _root.add2map(debris,2);this.soldierDebrisStampCount++;
        }
        this.soldierDebrisStamped=true;
    }
    this.soldierRoleBreak(body);
};

_root.敌人函数.配置音效("人类",this);
if(手枪==undefined)手枪="FR506";if(手枪2==undefined)手枪2="FR506";
