        if(this.cf6SkirtSign!=1 && this.cf6SkirtSign!=-1)this.cf6SkirtSign=this.soldierEvasionZSign()<0?-1:1;
        if(this.soldierTacticalMove(this.cf6SkirtSign<0?"上":"下",speedZ)<.1)this.cf6SkirtSign=-this.cf6SkirtSign;
